import{i as a}from"./chunk-5AQ7I6OD.js";import{a as e}from"./chunk-OOB6KUV2.js";var o={label:"What shipped, and why",body:"The game framing stays, in full. The prestige framing does not. One change carries almost all of it: the main quest is the problem, not the company. Four people on four networks who all have to see the same thing at the same instant \u2014 that is the boss fight, and it is a thing about the work rather than a thing about the logo. The side quests stay exactly as he wrote them, because they are the good part, and the achievements make them literal. Robinson survives as what it is: a hobby line in Off the clock, told as a joke against himself, which is where it is funniest and where it costs nothing.",keeps:["Challenger energy, side quests, achievements, easter eggs \u2014 the whole game layer.","Robinson, demoted from life goal to punchline, which improves it.","The range-not-scatter reframe, which is the genuinely valuable idea in his version."],drops:['"Working at Google is my dream" as the stated motive.',"Any suggestion that the last ten years were a run-up to this.","The claim of completion arriving before the evidence for it."]};var s=50,i=[{k:"Language",v:"TypeScript, strict, in modules with one job each"},{k:"Runtime dependencies",v:"None. No framework, no bundled library, nothing to audit"},{k:"State",v:"A pure reducer, which is the reason it can be unit-tested without a DOM"},{k:"Size",v:`An initial-load budget of ${s} kB gzip, enforced in CI so it cannot rot`},{k:"Loading",v:"Everything past the first screen is a deferred chunk, fetched only when reached"},{k:"Icons",v:"A ~7 kB subset of Material Symbols, Apache-2.0. Where the subset lacks a glyph, the path is authored and said to be authored"},{k:"Content",v:"One data module. The call view and the plain document view render from it, so they cannot disagree"},{k:"Hosting",v:"Static files from docs/ on GitHub Pages. No server, no build step at request time"}],n=[{k:"Measure, do not guess",v:"Geometry, colours and timings were read off the live product with getBoundingClientRect and getComputedStyle, not eyeballed from screenshots. Where a number could not be read \u2014 a native dialog, a canvas, an animation with no DOM \u2014 the notes say so rather than inventing one."},{k:"Say what is not cloned",v:"Some surfaces could not be measured at all, and those are ours by admission: the share picker is a drawing of a browser dialog, and the presenting layout was authored before it could be read."},{k:"No dead controls",v:"A control that cannot act is not rendered as a control. Rows that the original disables are disabled here too, and take no hover."},{k:"No Google marks",v:"No logos, no wordmarks, no borrowed artwork. The typeface subset is the one openly licensed piece."}];function c(){return e("div",{class:"bd"},e("p",{class:"bd-lead"},"A CV you can talk to rather than read. It opens as a video call because a call is a conversation, and a conversation is a better way to meet someone than a page of bullet points \u2014 the panels hold the cover letter, the captions carry a voice-over, and the shared screen holds the work itself."),e("p",{},"It is also, openly, a demonstration of agentic programming. One person and an agent built it in a week: the interface was measured off the real product rather than eyeballed, every task ran through the same three phases, and the corrections are in the commit log along with the retractions. The Timeline tab shows the shape of that; the Process tab shows the method."),e("h2",{},"Specifications"),e("dl",{class:"bd-rows"},...i.flatMap(t=>[e("dt",{},t.k),e("dd",{},t.v)])),e("h2",{},"Method"),e("dl",{class:"bd-rows"},...n.flatMap(t=>[e("dt",{},t.k),e("dd",{},t.v)])),e("h2",{},"Stack"),e("ul",{class:"bd-stack"},...a.primary.slice(0,5).map(t=>e("li",{},e("b",{},t.name)," \u2014 ",e("span",{},t.note)))),e("h2",{},"What shipped"),e("p",{},o.body),e("p",{class:"bd-note"},"The reviews, the board of what is still open, and the day-by-day history are the other tabs of this panel."))}export{c as a};
